sys_script.script:
(function executeRule(current, previous) {
    var tasks = [
        { short_description: 'Documentation Review', task_type: 'review', planned_hours: '40' },
        { short_description: 'Background Verification', task_type: 'deliverable', planned_hours: '80' },
        { short_description: 'Site Inspection', task_type: 'milestone', planned_hours: '24' },
        { short_description: 'Final Approval Gate', task_type: 'approval_gate', planned_hours: '16' }
    ];

    for (var i = 0; i < tasks.length; i++) {
        var task = new GlideRecord('x_1850489_premiu_0_prj_task');
        task.initialize();
        task.setValue('short_description', tasks[i].short_description);
        task.setValue('task_type', tasks[i].task_type);
        task.setValue('planned_hours', tasks[i].planned_hours);
        task.setValue('project', current.getUniqueValue());
        task.setValue('task_phase', 'not_started');
        task.setValue('state', '1');
        task.insert();
    }
})(current, previous);
